import os, sys, glob, re, hashlib, json

def get_sha256(filepath):
    try:
        with open(filepath, 'rb') as f:
            return hashlib.sha256(f.read()).hexdigest()
    except Exception:
        return None

def get_real_path(filepath):
    try:
        return os.path.realpath(filepath)
    except Exception:
        return os.path.abspath(filepath)

artifacts = []
seen = set()

def add_artifact(art):
    key = (art['type'], art['path'], art['details']['line_number'], art['details']['content_preview'])
    if key not in seen:
        seen.add(key)
        artifacts.append(art)

# 1. Cron scanner
def scan_cron_file(filepath):
    real_path = get_real_path(filepath)
    if not os.path.isfile(real_path):
        return
    sha = get_sha256(real_path)
    if not sha:
        return

    try:
        with open(real_path, 'r', encoding='utf-8', errors='ignore') as f:
            lines = f.readlines()
    except Exception:
        return

    user = None
    if '/var/spool/cron/crontabs/' in real_path or '/var/spool/cron/' in real_path:
        user = os.path.basename(real_path)

    for idx, line in enumerate(lines, 1):
        sline = line.strip()
        if not sline or sline.startswith('#'):
            continue
        if re.match(r'^[A-Za-z_][A-Za-z0-9_]*\s*=', sline):
            continue

        is_suspicious = False
        if re.search(r'/(tmp|var/tmp|dev/shm)/', sline):
            is_suspicious = True
        elif re.search(r'\b(nc|ncat|netcat|socat|curl|wget|bash\s+-i|sh\s+-i|python[23]?\s+-c|perl\s+-e|ruby\s+-e|eval|base64)\b|/dev/tcp/', sline):
            is_suspicious = True
        elif any(path in sline for path in ['/app_target/', '/usr/local/', '/opt/', '/home/', '/root/']):
            is_suspicious = True
        elif sline.startswith('* * * * *') or sline.startswith('*/1 * * * *'):
            if not any(std in sline for std in ['run-parts', 'anacron']):
                is_suspicious = True

        if is_suspicious:
            cron_user = user
            if not cron_user:
                tokens = sline.split()
                if len(tokens) >= 7:
                    possible_user = tokens[5]
                    if re.match(r'^[a-z_][a-z0-9_-]*\$?$', possible_user):
                        cron_user = possible_user

            add_artifact({
                'type': 'cron_job',
                'path': real_path,
                'sha256': sha,
                'details': {
                    'line_number': idx,
                    'content_preview': sline[:100],
                    'user': cron_user
                }
            })

# 2. Systemd scanner
def scan_systemd_file(filepath):
    real_path = get_real_path(filepath)
    if not os.path.isfile(real_path):
        return
    sha = get_sha256(real_path)
    if not sha:
        return

    fname = os.path.basename(real_path)
    if fname in ('.', '..'):
        return

    is_hidden = fname.startswith('.')

    try:
        with open(real_path, 'r', encoding='utf-8', errors='ignore') as f:
            content = f.read()
            lines = content.splitlines()
    except Exception:
        return

    exec_lines = []
    for idx, line in enumerate(lines, 1):
        sline = line.strip()
        if re.match(r'^Exec(Start|StartPre|StartPost|Reload|Stop)\s*=', sline):
            exec_lines.append((idx, sline))

    is_suspicious = False
    relevant_line = None

    if is_hidden:
        is_suspicious = True
        if exec_lines:
            relevant_line = exec_lines[0][1]
        else:
            for line in lines:
                if line.strip() and not line.strip().startswith('#'):
                    relevant_line = line.strip()
                    break
            if not relevant_line:
                relevant_line = f'Hidden unit file: {fname}'
    else:
        for lno, el in exec_lines:
            if (re.search(r'/(tmp|var/tmp|dev/shm)/', el) or
                re.search(r'\b(nc|ncat|netcat|socat|curl|wget|python[23]?\s+-c|eval|base64)\b|/dev/tcp/', el) or
                any(p in el for p in ['/app_target/', '/opt/', '/home/', '/root/']) or
                'while true' in el or 'attacker.com' in el):
                is_suspicious = True
                relevant_line = el
                break

    if is_suspicious and relevant_line:
        add_artifact({
            'type': 'systemd_unit',
            'path': real_path,
            'sha256': sha,
            'details': {
                'line_number': None,
                'content_preview': relevant_line[:100],
                'user': None
            }
        })

# 3. rc.local scanner
def scan_rc_local_file(filepath):
    real_path = get_real_path(filepath)
    if not os.path.isfile(real_path):
        return
    sha = get_sha256(real_path)
    if not sha:
        return

    try:
        with open(real_path, 'r', encoding='utf-8', errors='ignore') as f:
            lines = f.readlines()
    except Exception:
        return

    for idx, line in enumerate(lines, 1):
        sline = line.strip()
        if not sline or sline.startswith('#'):
            continue
        if sline in ('exit 0', 'exit', 'exit 1'):
            continue
        if sline in ('touch /var/lock/subsys/local',):
            continue

        add_artifact({
            'type': 'rc_local',
