    user = 'root' if '/root/' in real_path else None
    m = re.search(r'/home/([^/]+)/', real_path)
    if m:
        user = m.group(1)

    try:
        with open(real_path, 'r', encoding='utf-8', errors='ignore') as f:
            lines = f.readlines()
    except Exception:
        return

    for idx, line in enumerate(lines, 1):
        sline = line.strip()
        if not sline or sline.startswith('#'):
            continue

        is_suspicious = False
        is_legit = any(pattern in sline for pattern in LEGIT_KEY_PATTERNS)
        has_suspicious_comment = any(kw in sline for kw in ['attacker', 'malicious', 'backdoor', 'unknown', 'hack', 'evil', 'temp', 'test', 'anon', 'ghost'])

        if not is_legit or has_suspicious_comment or '/app_target/' in real_path:
            is_suspicious = True

        if is_suspicious:
            add_artifact({
                'type': 'ssh_key',
                'path': real_path,
