cron_paths = glob.glob('/etc/cron*/*') + glob.glob('/etc/crontab') + glob.glob('/var/spool/cron/crontabs/*') + glob.glob('/var/spool/cron/*')
for p in cron_paths:
    scan_cron_file(p)

systemd_paths = glob.glob('/etc/systemd/system/**/*.*', recursive=True) + glob.glob('/etc/systemd/system/*') + glob.glob('/usr/lib/systemd/system/**/*.*', recursive=True) + glob.glob('/usr/lib/systemd/system/*') + glob.glob('/usr/lib/systemd/system/.*')
for p in systemd_paths:
    scan_systemd_file(p)

rc_paths = ['/etc/rc.local', '/etc/rc.d/rc.local']
for p in rc_paths:
    scan_rc_local_file(p)

ssh_paths = glob.glob('/home/*/.ssh/authorized_keys') + glob.glob('/root/.ssh/authorized_keys')
for p in ssh_paths:
    scan_ssh_key_file(p)

# Scan /app_target if exists
if os.path.exists('/app_target'):
    for root, dirs, files in os.walk('/app_target'):
        for file in files:
            fp = os.path.join(root, file)
            rpath = get_real_path(fp)
            if 'cron' in rpath:
                scan_cron_file(rpath)
            elif 'systemd' in rpath or rpath.endswith(('.service', '.timer', '.socket', '.target')) or os.path.basename(rpath).startswith('.'):
                scan_systemd_file(rpath)
            elif rpath.endswith('rc.local'):
                scan_rc_local_file(rpath)
            elif rpath.endswith('authorized_keys'):
                scan_ssh_key_file(rpath)

