def sort_key(art):
    lno = art['details']['line_number']
    return (art['type'], art['path'], lno if lno is not None else -1)

artifacts.sort(key=sort_key)

cron_cnt = sum(1 for a in artifacts if a['type'] == 'cron_job')
systemd_cnt = sum(1 for a in artifacts if a['type'] == 'systemd_unit')
rc_cnt = sum(1 for a in artifacts if a['type'] == 'rc_local')
ssh_cnt = sum(1 for a in artifacts if a['type'] == 'ssh_key')

report = {
    'summary': {
        'total_artifacts': len(artifacts),
        'cron_jobs': cron_cnt,
        'systemd_units': systemd_cnt,
        'rc_local_modifications': rc_cnt,
        'ssh_keys': ssh_cnt
    },
    'artifacts': artifacts
}

print(json.dumps(report, indent=2))
